/*
 * The chat screen. Composes var(--echo-*) only.
 *
 * The material rule it follows: running text gets no container. Incoming
 * messages are text on the page's own ground; outgoing messages sit in a
 * recessed well — the composer's material — and the Send cap is the one
 * raised, lit object. A bubble per message would be forty molded cards on one
 * screen.
 */
.echo-chat {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto auto;
  box-sizing: border-box;
  width: 100%;
  max-width: 46rem;
  height: min(100dvh, 48rem);
  margin: 0 auto;
  padding: clamp(1.25rem, 4vw, 2rem) clamp(1rem, 4vw, 2rem);
  color: var(--echo-text);
}

.echo-chat__head {
  display: flex;
  align-items: center;
  gap: var(--echo-space-6);
  padding-bottom: var(--echo-space-8);
  border-bottom: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}

.echo-chat__who {
  display: grid;
  gap: var(--echo-space-1);
  min-width: 0;
}

.echo-chat__name {
  margin: 0;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-bold, 700);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.echo-chat__sub {
  display: inline-flex;
  align-items: center;
  gap: var(--echo-space-3);
  min-width: 0;
  font-family: var(--echo-font-mono, ui-monospace, monospace);
  font-size: var(--echo-text-2xs);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  color: var(--echo-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.echo-chat__thread {
  display: flex;
  flex-direction: column;
  gap: var(--echo-space-6);
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--echo-space-10) var(--echo-space-1);
  scrollbar-width: thin;
  scrollbar-color: var(--echo-cap) transparent;
}

.echo-chat__day {
  align-self: center;
  margin: 0 0 var(--echo-space-4);
  font-family: var(--echo-font-mono, ui-monospace, monospace);
  font-size: var(--echo-text-3xs);
  letter-spacing: var(--echo-tracking-label, 0.2em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

.echo-chat__msg {
  display: grid;
  align-items: end;
  gap: var(--echo-space-2) var(--echo-space-5);
  max-width: 86%;
}

.echo-chat__msg[data-grouped] {
  margin-top: calc(var(--echo-space-3) * -1);
}

.echo-chat__msg[data-from="them"] {
  /* The avatar column is in rem, like the avatar it holds, so both grow
     together when a reader raises their text size. */
  grid-template-columns: 2rem minmax(0, 1fr);
  justify-self: start;
  align-self: flex-start;
}

.echo-chat__msg[data-from="me"] {
  grid-template-columns: minmax(0, 1fr);
  justify-items: end;
  align-self: flex-end;
}

.echo-chat__avatar {
  grid-row: 1;
  display: flex;
  align-items: flex-end;
}

.echo-chat__bubble {
  min-width: 0;
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
  /* Long words and URLs wrap inside the column, never open it. */
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

/* Theirs: no container. Text on the ground. */
.echo-chat__msg[data-from="them"] .echo-chat__bubble {
  padding: var(--echo-space-2) 0;
}

/* Yours: the composer's recessed well, so what you typed keeps its material. */
.echo-chat__msg[data-from="me"] .echo-chat__bubble {
  padding: var(--echo-space-5) var(--echo-space-7);
  border-radius: var(--echo-radius-xl);
  border-end-end-radius: var(--echo-radius-xs);
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  box-shadow:
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.55 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-chat__time {
  font-family: var(--echo-font-mono, ui-monospace, monospace);
  font-size: var(--echo-text-3xs);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  color: var(--echo-text-dim);
}

.echo-chat__msg[data-from="them"] .echo-chat__time {
  grid-column: 2;
}

.echo-chat__msg[data-grouped] .echo-chat__time {
  display: none;
}

/* Visually hidden speaker name, so the log reads "You: …" / "Echo: …". */
.echo-chat__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* The indicator keeps its row even when empty, so the composer never jumps. */
.echo-chat__typing {
  display: flex;
  align-items: center;
  min-height: var(--echo-space-10);
  padding: 0 var(--echo-space-1) var(--echo-space-4);
}

.echo-chat__composer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: var(--echo-space-6);
  padding-top: var(--echo-space-8);
  border-top: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}

/*
 * The composer's textarea has to be able to shrink inside the flex row.
 *
 * Reached by descendant selector rather than by handing Textarea a
 * `className`: Echo components are closed (PRINCIPLES.md), and a parent
 * styling a child through the child's own documented class is how a template
 * does layout without reopening the component's API.
 */
.echo-chat__composer .echo-textarea {
  min-width: 0;
}

.echo-chat__hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--echo-space-3);
  margin: var(--echo-space-5) 0 0;
  font-size: var(--echo-text-2xs);
  color: var(--echo-text-dim);
}

@media (max-width: 560px) {
  .echo-chat__msg {
    max-width: 100%;
  }
  /* A phone has no Enter-to-send convention worth teaching; the cap is it. */
  .echo-chat__hint {
    display: none;
  }
}

/*
 * One row of text is 22px — under the 24px target minimum (WCAG 2.5.8) and a
 * poor tap target. The floor is one default control, which also lines the
 * composer's well up with the Send cap beside it. Autosize still grows it.
 */
.echo-chat__composer .echo-textarea__input {
  min-height: var(--echo-control-default);
}

"use client";

/**
 * The chat screen (a template, like auth / settings / console).
 *
 * One conversation as a front panel: a header with who you are talking to and
 * whether they are there, the thread, and a composer. What it proves is the
 * thing the other three templates do not reach — whether the material
 * language survives RUNNING TEXT, where most of the screen is words rather
 * than controls.
 *
 * The answer it commits to is restraint:
 *   - incoming messages have no container at all — text beside an avatar;
 *   - outgoing messages sit in a recessed well, the same material as the
 *     composer they were typed into, so "what I wrote" reads as one thing
 *     from the textarea to the thread;
 *   - the only raised, lit object on the screen is the Send cap.
 *
 * No backend: `onSend` hands you the text and may return (or resolve to) the
 * reply. Without it the screen answers from `replies`, so it is alive as a
 * demo.
 */
import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Avatar } from "../avatar";
import { Textarea } from "../textarea";
import { HardwareButton } from "../hardware-button";
import { Loader } from "../loader";
import { StatusDot } from "../status-dot";
import { Kbd } from "../kbd";
import "./chat.css";

export interface ChatMessage {
  id: string;
  from: "me" | "them";
  text: string;
  /** Shown as-is, in the machine voice. */
  time: string;
}

export interface ChatScreenProps {
  /**
   * This screen is inside another page: the title drops to <h2>, so the page
   * keeps one <h1>. Never set it on the screen that owns the page.
   */
  embedded?: boolean;
  /** Who you are talking to. */
  participant?: string;
  /** Under the name: a role, a channel, a device. */
  subtitle?: string;
  /** The thread so far, oldest first. Defaults to a demo conversation. */
  messages?: ChatMessage[];
  /**
   * Called with what you sent. Return (or resolve to) the reply text to have
   * it appear after the typing indicator; return nothing to reply yourself
   * later through `messages`.
   */
  onSend?: (text: string) => string | void | Promise<string | void>;
  /** Canned replies, cycled, used only when there is no `onSend`. */
  replies?: string[];
}

const DEMO: ChatMessage[] = [
  { id: "m1", from: "them", time: "09:41", text: "Morning. The take from last night is on the device — 4:12, peaking at −3 dB." },
  { id: "m2", from: "me", time: "09:43", text: "Can you trim the first eight seconds? There is a chair squeak before the count-in." },
  { id: "m3", from: "them", time: "09:43", text: "Trimmed. The count-in now starts on the downbeat." },
];

const DEMO_REPLIES = [
  "Done. It is on the device.",
  "Noted — I will keep that for the next session.",
  "Saved. Changes apply to this device only.",
];

const clock = () => {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
};

function SendIcon() {
  return (
    <svg width="100%" height="100%" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 8h9M8.5 4.5 12 8l-3.5 3.5" />
    </svg>
  );
}

export function ChatScreen({
  embedded,
  participant = "Echo",
  subtitle = "Session assistant",
  messages: initial = DEMO,
  onSend,
  replies = DEMO_REPLIES,
}: ChatScreenProps) {
  const [messages, setMessages] = useState<ChatMessage[]>(initial);
  const [draft, setDraft] = useState("");
  const [typing, setTyping] = useState(false);
  const replyIndex = useRef(0);
  const nextId = useRef(0);
  const thread = useRef<HTMLDivElement>(null);
  const Title = embedded ? "h2" : "h1";

  // Keep the newest message in view. Scrolling the thread, not the page: an
  // embedded screen must never yank the document it sits in.
  useEffect(() => {
    const el = thread.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages, typing]);

  const push = (from: ChatMessage["from"], text: string) =>
    setMessages((list) => [...list, { id: `n${nextId.current++}`, from, text, time: clock() }]);

  async function send() {
    const text = draft.trim();
    if (!text || typing) return;
    push("me", text);
    setDraft("");
    setTyping(true);
    try {
      let reply: string | void;
      if (onSend) {
        reply = await onSend(text);
      } else {
        // A short, honest pause: long enough to see the indicator, short
        // enough that the demo does not feel slow.
        await new Promise((r) => setTimeout(r, 900));
        reply = replies[replyIndex.current++ % Math.max(replies.length, 1)];
      }
      if (reply) push("them", reply);
    } finally {
      setTyping(false);
    }
  }

  function onKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    // Enter sends; Shift+Enter is a new line. IME composition must not send.
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      void send();
    }
  }

  return (
    <div className="echo-chat">
      <header className="echo-chat__head">
        <Avatar name={participant} size="md" />
        <div className="echo-chat__who">
          <Title className="echo-chat__name">{participant}</Title>
          <span className="echo-chat__sub">
            <StatusDot on decorative />
            online · {subtitle}
          </span>
        </div>
      </header>

      {/*
        role="log": new messages are announced politely, in order, and the
        history is not re-read. The typing indicator lives OUTSIDE it — it is
        its own status region (Loader), and a log that announced "typing"
        between every message would be noise.
      */}
      <div className="echo-chat__thread" ref={thread} role="log" aria-label={`Conversation with ${participant}`}>
        <p className="echo-chat__day">Today</p>
        {messages.map((m, i) => {
          const prev = messages[i - 1];
          const grouped = prev?.from === m.from;
          return (
            <div
              key={m.id}
              className="echo-chat__msg"
              data-from={m.from}
              data-grouped={grouped || undefined}
            >
              {m.from === "them" && (
                <span className="echo-chat__avatar" aria-hidden="true">
                  {!grouped && <Avatar name={participant} size="sm" />}
                </span>
              )}
              <div className="echo-chat__bubble">
                <span className="echo-chat__sr">{m.from === "me" ? "You" : participant}: </span>
                {m.text}
              </div>
              <span className="echo-chat__time">{m.time}</span>
            </div>
          );
        })}
      </div>

      <div className="echo-chat__typing" data-on={typing || undefined}>
        {typing && <Loader dot={7} label={`${participant} is typing`} />}
      </div>

      <form
        className="echo-chat__composer"
        onSubmit={(e) => {
          e.preventDefault();
          void send();
        }}
      >
        <Textarea
          aria-label={`Message ${participant}`}
          placeholder={`Message ${participant}`}
          value={draft}
          onValueChange={setDraft}
          onKeyDown={onKeyDown}
          rows={1}
          maxRows={6}
        />
        <HardwareButton
          type="submit"
          variant="primary"
          iconOnly
          aria-label="Send"
          icon={<SendIcon />}
          disabled={!draft.trim() || typing}
        />
      </form>
      <p className="echo-chat__hint">
        <Kbd>↩</Kbd> to send · <Kbd>⇧</Kbd> <Kbd>↩</Kbd> for a new line
      </p>
    </div>
  );
}
